insert into profiles(id,username,full_name) select id, split_part(email,'@',1), case split_part(email,'@',1) when 'minister' then 'وزير تجريبي' when 'soldier1' then 'جندي أول تجريبي' else 'جندي ثان تجريبي' end from auth.users;
insert into personnel(user_id,military_number,rank_id,department_id) select p.id, case p.username when 'minister' then 'T-0001' when 'soldier1' then 'T-0002' else 'T-0003' end, (select id from ranks where code = case p.username when 'minister' then 'minister' else 'private' end), case p.username when 'minister' then null when 'soldier1' then (select id from departments where code='army') else (select id from departments where code='navy') end from profiles p;
insert into user_roles(user_id,role_id) select p.id,r.id from profiles p join roles r on (p.username='minister' and r.code in ('minister','system_administrator')) or (p.username<>'minister' and r.code='soldier');
